/**
 * GPU-accelerated 3D Gaussian Splatting renderer for Three.js WebGPU.
 *
 * **Features**
 * - WebGPU compute pipeline for frustum culling and depth sorting
 * - Efficient packed data format (32 bytes/splat base)
 * - Optional spherical harmonics (SH degree 0-3) for view-dependent color
 * - Radix sort for O(n) back-to-front depth ordering
 * - Billboard quad generation in vertex shader
 * - Anisotropic Gaussian rendering with 2D covariance projection
 *
 * **Usage**
 * ```js
 * import { GaussianSplats, GaussianSplatsLoader } from '@three-blocks/core';
 * import * as THREE from 'three/webgpu';
 *
 * const renderer = new THREE.WebGPURenderer();
 * await renderer.init();
 *
 * const loader = new GaussianSplatsLoader();
 * const splats = await loader.loadAsync('/models/scene.ply');
 * scene.add(splats);
 *
 * function animate() {
 *   splats.update(renderer, camera);
 *   renderer.render(scene, camera);
 * }
 * ```
 *
 * @class GaussianSplats
 * @extends THREE.Object3D
 * @short GPU Gaussian Splatting with compute culling, radix depth sort, and anisotropic quad rendering.
 * @category Rendering
 * @tags WebGPU
 */
export class GaussianSplats {
    /**
     * Create a Gaussian Splatting renderer.
     *
     * @param {Object} [options={}] Configuration options.
     * @param {number} [options.maxSplats=1000000] Maximum splat capacity.
     * @param {boolean} [options.enableSH=true] Enable spherical harmonics for view-dependent color.
     * @param {number} [options.shDegree=2] SH degree (0-3). Higher = more view-dependent detail.
     * @param {boolean} [options.frustumCulling=true] Enable GPU frustum culling.
     * @param {number} [options.frustumPadding=0.1] Frustum padding factor.
     * @param {boolean} [options.sortEnabled=true] Enable depth sorting (required for correct transparency).
     * @param {string} [options.sortMode='radial'] Sort mode: 'radial' (distance from camera, SparkJS default) or 'depth' (Z-depth).
     * @param {string} [options.sortPrecision='float16'] Sort precision: 'float16' (faster, default) or 'float32' (precise but 2x slower).
     * @param {string} [options.sortAlgorithm='radix'] Sort algorithm: 'radix' (O(n), default) or 'bitonic' (O(n log²n)).
     * @param {boolean} [options.temporalStability=true] Skip re-sorting when camera barely moves (optimization).
     * @param {number} [options.maxStdDev=Math.sqrt(8)] Max Gaussian extent in std devs. sqrt(8)≈2.83 default, sqrt(5)≈2.24 for VR/mobile.
     * @param {THREE.Material} [options.material] Custom material override.
     */
    constructor(options?: {
        maxSplats?: number;
        enableSH?: boolean;
        shDegree?: number;
        frustumCulling?: boolean;
        frustumPadding?: number;
        sortEnabled?: boolean;
        sortMode?: string;
        sortPrecision?: string;
        sortAlgorithm?: string;
        temporalStability?: boolean;
        maxStdDev?: number;
        material?: THREE.Material;
    });
    /** Flag for type checking. */
    isGaussianSplats: boolean;
    /** @private */
    private _coordTransform;
    /** @type {number} Current number of splats loaded. */
    count: number;
    /** @type {number} Maximum splat capacity (set in setData based on actual count). */
    maxSplats: number;
    /** @type {number} Requested max splats from options. */
    _requestedMaxSplats: number;
    /** @type {boolean} Whether spherical harmonics are enabled (backing field). */
    _enableSH: boolean;
    /** @type {number} Spherical harmonics degree 0-3 (backing field). */
    _shDegree: number;
    /** @type {number} Maximum SH degree available from loaded data. */
    _maxDataSHDegree: number;
    /** @type {boolean} Whether frustum culling is enabled. */
    frustumCullingEnabled: boolean;
    /** @type {boolean} Whether depth sorting is enabled. */
    sortEnabled: boolean;
    /** @type {string} Sort mode: 'radial' (distance from camera, SparkJS default) or 'depth' (Z-depth). */
    sortMode: string;
    /** @type {string} Sort precision: 'float32' (precise, default) or 'float16' (faster but may cause artifacts). */
    sortPrecision: string;
    /** @type {string} Sort algorithm: 'radix' (O(n), default) or 'bitonic' (O(n log²n)). */
    sortAlgorithm: string;
    /** @type {number} Maximum Gaussian extent in standard deviations. sqrt(8)≈2.83 default, sqrt(5)≈2.24 for VR/mobile. */
    maxStdDev: number;
    /** @type {boolean} Whether to skip re-sorting when camera barely moves (temporal stability optimization). */
    temporalStability: boolean;
    /** @type {THREE.Material|null} Custom material override. */
    _customMaterial: THREE.Material | null;
    /** @type {number} Frustum padding value. */
    _frustumPadding: number;
    buffers: {
        positionsScales: any;
        rotationsColors: any;
        shCoefficients: any;
        shContributionData: any;
        worldPositionData: any;
        projected: any;
        sortKeys: any;
        sortIndices: any;
        sortPairs: any;
        chunkBounds: any;
        visibleChunks: any;
    };
    sortCount: number;
    uniforms: {
        modelMatrix: any;
        inverseModelMatrix: any;
        viewMatrix: any;
        projMatrix: any;
        viewProjMatrix: any;
        cameraPosition: any;
        screenSize: any;
        frustumPadding: any;
        focalLength: any;
        splatCount: any;
        visibleCount: any;
        near: any;
        far: any;
        tanFovY: any;
        tanFovX: any;
        maxStdDev: any;
        numChunks: any;
        frustumPlanes: any;
    };
    /** Number of splats per chunk (matches workgroup size). @type {number} */
    _chunkSize: number;
    /** Number of chunks. @type {number} */
    _numChunks: number;
    /** Chunk AABB bounds data. @type {Float32Array|null} */
    _chunkBoundsData: Float32Array | null;
    _initialized: boolean;
    _needsUpdate: boolean;
    _renderer: any;
    _sorter: ComputeBitonicSort | ComputeRadixSort;
    _mesh: any;
    _lastCameraPosition: any;
    _lastCameraDirection: any;
    _lastScreenSize: any;
    _cameraMoved: boolean;
    _firstFrameRendered: boolean;
    /**
     * Extract frustum planes from view-projection matrix.
     * Updates this.uniforms.frustumPlanes with 6 normalized plane equations.
     * @private
     * @param {THREE.Matrix4} viewProjMatrix - Combined view-projection matrix.
     */
    private _updateFrustumPlanes;
    /**
     * Create sort keys buffer filled with sentinel values.
     * Prevents first-frame artifacts by ensuring all keys sort to the end initially.
     * @private
     * @param {number} count Buffer size.
     * @returns {Uint32Array} Buffer filled with sentinel values.
     */
    private _createSortKeysBuffer;
    /**
     * Create sequential index buffer [0, 1, 2, ...].
     * Prevents first-frame artifacts from all-zero indices.
     * @private
     * @param {number} count Buffer size.
     * @returns {Uint32Array} Buffer with sequential indices.
     */
    private _createSequentialBuffer;
    /**
     * Create sort pairs buffer with (sentinel, index) pairs for bitonic sort.
     * @private
     * @param {number} count Number of pairs.
     * @returns {Uint32Array} Buffer with uvec2 pairs (key, index).
     */
    private _createSortPairsBuffer;
    /**
     * Allocate GPU storage buffers.
     * @private
     */
    private _allocateBuffers;
    _indirectDispatchBuffer: any;
    _indirectDispatchNode: any;
    indirect: any;
    drawStructNode: any;
    /**
     * Build compute shader passes.
     * Implements 2-pass hierarchical frustum culling with indirect dispatch.
     * @private
     */
    private _buildCompute;
    _computeClear: any;
    _computeResetAll: any;
    _computeChunkCull: any;
    _computeProjectIndirect: any;
    _computeCullProject: any;
    _computeCapCount: any;
    /**
     * Create the mesh with instanced geometry.
     * @private
     */
    private _createMesh;
    material: any;
    staticGroup: any;
    /**
     * Rebuild the material.
     * @private
     */
    private _rebuildMaterial;
    /**
     * Set splat data from parsed arrays.
     *
     * @param {Object} data Parsed splat data.
     * @param {Float32Array} data.positions Position array (3 floats per splat).
     * @param {Float32Array} data.scales Scale array (3 floats per splat, log-space).
     * @param {Float32Array} data.rotations Rotation array (4 floats per splat, quaternion).
     * @param {Float32Array} data.colors Color array (4 floats per splat, RGBA).
     * @param {Float32Array} [data.shCoefficients] Optional SH coefficients.
     * @param {number} data.count Number of splats.
     * @param {number} [data.shDegree] SH degree from loaded data.
     */
    setData(data: {
        positions: Float32Array;
        scales: Float32Array;
        rotations: Float32Array;
        colors: Float32Array;
        shCoefficients?: Float32Array;
        count: number;
        shDegree?: number;
    }): void;
    /**
     * Update splat rendering for current camera.
     * Call this before rendering each frame.
     *
     * @param {THREE.WebGPURenderer} renderer WebGPU renderer.
     * @param {THREE.Camera} camera Active camera.
     */
    update(renderer: THREE.WebGPURenderer, camera: THREE.Camera): void;
    /**
     * Enable/disable indirect draw debug logging.
     * When enabled, logs instanceCount after each compute pass.
     * @type {boolean}
     */
    set debugIndirect(value: any);
    get debugIndirect(): any;
    _debugIndirect: any;
    /**
     * Get current visible splat count.
     * Note: This reads from CPU-side array which may not reflect GPU value.
     * Use readIndirectArgs() for accurate GPU readback.
     * @type {number}
     * @readonly
     */
    readonly get visibleCount(): number;
    /**
     * Read back indirect draw arguments from GPU (debug/stats).
     *
     * @returns {Promise<Uint32Array|null>} Array of 5 values: [indexCount, instanceCount, firstIndex, baseVertex, firstInstance], or null if not ready.
     */
    readIndirectArgs(): Promise<Uint32Array | null>;
    /**
     * Set whether spherical harmonics are enabled.
     * Triggers compute shader rebuild when changed.
     * @param {boolean} value - Enable or disable SH.
     */
    set enableSH(value: boolean);
    /**
     * Get whether spherical harmonics are enabled.
     * @type {boolean}
     */
    get enableSH(): boolean;
    /**
     * Set the spherical harmonics degree (0-3).
     * Clamped to the maximum degree available from loaded data.
     * Triggers compute shader rebuild when changed.
     * @param {number} value - SH degree (0 = DC only, 1-3 = higher order harmonics).
     */
    set shDegree(value: number);
    /**
     * Get the current spherical harmonics degree.
     * @type {number}
     */
    get shDegree(): number;
    /**
     * Get the maximum SH degree available from loaded data.
     * @type {number}
     * @readonly
     */
    readonly get maxDataSHDegree(): number;
    /**
     * Read back sorted data from GPU for debugging.
     * @param {WebGPURenderer} renderer - The WebGPU renderer.
     * @returns {Promise<{keys: Uint32Array, indices: Uint32Array}>} Sorted keys and indices buffers.
     */
    readback(renderer: WebGPURenderer): Promise<{
        keys: Uint32Array;
        indices: Uint32Array;
    }>;
    /**
     * Attach GUI controls.
     *
     * @param {Object} folder GUI folder instance.
     */
    attachGUI(folder: any): void;
    _guiFolder: any;
    _statsInterval: number;
    /**
     * Dispose of GPU resources.
     */
    dispose(): void;
}
import { ComputeBitonicSort } from '../Compute/ComputeBitonicSort.js';
import { ComputeRadixSort } from '../Compute/ComputeRadixSort.js';
